update public.learning_paths
set
  title = 'Statistics for Economics',
  goal = 'Statistics for Economics',
  summary = 'This syllabus covers a conventional second-year economics statistics course, while also adding graduate-facing probability foundations, estimator quality, maximum likelihood, robust regression inference, limited dependent variables, causal research design, reproducible computing, and a capstone empirical economics project.',
  data = $stecjson${"slug": "statistics-for-economics", "title": "Statistics for Economics", "description": "This syllabus covers a conventional second-year economics statistics course, while also adding graduate-facing probability foundations, estimator quality, maximum likelihood, robust regression inference, limited dependent variables, causal research design, reproducible computing, and a capstone empirical economics project.", "topics": [{"id": "3e3ffd10-cc2c-4d0f-9062-80f293772e5a", "type": "topic", "title": "Economic Data and Statistical Thinking", "description": "Students learn to turn economic questions into measurable variables, datasets, uncertainty claims, and empirical strategies.", "children": [{"id": "3eaf8462-1175-4503-9566-fa30cddb9e74", "type": "subtopic", "title": "Economic questions and estimands", "children": [{"id": "b0cd485c-7ed1-4c41-827f-f143f9d6fb3a", "type": "concept", "title": "Population versus sample"}, {"id": "f7122aeb-79f4-4772-a7ae-fd274701bb8c", "type": "concept", "title": "Parameters, estimators, and estimates"}, {"id": "e80fa155-d9de-4d25-abbf-1b0e86db817e", "type": "concept", "title": "Descriptive, predictive, and causal questions"}], "description": "The point is to state exactly what quantity or relationship the analysis is trying to learn."}, {"id": "b085b733-8d74-450d-a0d0-5ccfda09a081", "type": "subtopic", "title": "Economic data sources", "children": [{"id": "04def940-343a-4637-a3f1-bf11f80c8400", "type": "concept", "title": "Surveys, administrative data, experiments, and market data"}, {"id": "bf92cc1b-ffa4-4385-b181-cc9724976828", "type": "concept", "title": "Cross-sectional, time-series, and panel data"}, {"id": "b9eeba06-04d3-404e-99e5-bbb5218bc019", "type": "concept", "title": "Measurement units, deflators, and indexing"}], "description": "Students learn how the source of data shapes what can be claimed."}, {"id": "55b4ab9d-3f7c-4b82-afef-cb6bac07d331", "type": "subtopic", "title": "Data ethics and validity", "children": [{"id": "6360bf37-643b-4b5b-a994-817881a87a79", "type": "concept", "title": "Confidentiality and disclosure risk"}, {"id": "6b5dec53-2acc-40e9-b3b6-b33c5e9ae56b", "type": "concept", "title": "Selection bias and missingness"}, {"id": "87f56caf-bbb3-4256-af27-300cd27eb7ed", "type": "concept", "title": "Responsible communication of uncertainty"}], "description": "Economic data represent people, firms, and institutions, so validity and privacy matter."}]}, {"id": "fac3496e-c163-4fb0-9125-6300d370b7c0", "type": "topic", "title": "Descriptive Statistics and Economic Data Visualization", "description": "This topic builds fluency in summarizing distributions, inequality, growth, labor-market patterns, and other economic data.", "children": [{"id": "ef54da79-c605-4a4a-8d4c-6fc1933889cc", "type": "subtopic", "title": "Distribution summaries", "children": [{"id": "54953511-f64e-4eb7-9e4d-16135fd290d7", "type": "concept", "title": "Mean, median, mode, quantiles"}, {"id": "67e5b8ac-9d8d-4cc5-9b4a-d131d4883c66", "type": "concept", "title": "Variance, standard deviation, IQR"}, {"id": "34374fa0-94f9-4227-a18e-ac8db243a331", "type": "concept", "title": "Skewness, tails, and outliers"}], "description": "Descriptive statistics reveal central tendency, dispersion, skewness, and outliers before modeling begins."}, {"id": "bc16e7ad-07fc-4bd3-9ab8-714b0768af73", "type": "subtopic", "title": "Economic comparisons", "children": [{"id": "6e09ac7f-0612-4074-b63b-fa366aef8ed2", "type": "concept", "title": "Rates, ratios, and index numbers"}, {"id": "06bdb479-03ea-437a-9ebc-d4a6a41de8c4", "type": "concept", "title": "Real versus nominal values"}, {"id": "ca59ff81-4e81-49ff-9451-4d1b43b1132c", "type": "concept", "title": "Growth rates and log changes"}], "description": "Students learn to compare groups, periods, regions, and markets carefully."}, {"id": "96e3d3e1-def6-4e33-9460-e563d4a4f8e0", "type": "subtopic", "title": "Visualization", "children": [{"id": "7ddbdb86-b7e5-4a3f-8df2-7a7ba55cec86", "type": "concept", "title": "Histograms, density plots, and boxplots"}, {"id": "8121ba67-b0c3-4158-b6da-1a01d9068d93", "type": "concept", "title": "Scatterplots and fitted lines"}, {"id": "640817ac-d769-4c07-8df1-899a3739743d", "type": "concept", "title": "Time-series plots and small multiples"}], "description": "Good economic graphics expose patterns and prevent hidden modeling mistakes."}]}, {"id": "626cd6dc-5797-475f-938b-87767a8e9a6e", "type": "topic", "title": "Probability for Economic Decision-Making", "description": "Probability gives economists a language for uncertainty, risk, beliefs, and repeated sampling.", "children": [{"id": "60856e6c-5282-4efb-91bc-4670f4844680", "type": "subtopic", "title": "Probability rules", "children": [{"id": "7a71bdbb-bf47-46e9-a51f-9f9cc80e3f67", "type": "concept", "title": "Events, complements, unions, and intersections"}, {"id": "5ce4c442-76cd-40f0-9bbb-0e2f0a31c2c7", "type": "concept", "title": "Conditional probability"}, {"id": "5dc25e61-9b0d-4ff7-a3f3-86d1d9fed26f", "type": "concept", "title": "Independence and mutual exclusivity"}], "description": "Probability formalizes uncertainty in economic decisions and empirical samples."}, {"id": "23008e38-9ec1-4b31-a847-6bb2dd69fb1f", "type": "subtopic", "title": "Bayes and beliefs", "children": [{"id": "4118e1ce-ddc6-4a06-bbea-3792d4eca376", "type": "concept", "title": "Bayes' rule"}, {"id": "285f2512-4cad-4b7c-a40d-7938d6352295", "type": "concept", "title": "Base rates"}, {"id": "33c2809c-5521-4548-9670-4dda4d604dde", "type": "concept", "title": "Diagnostic and forecasting examples"}], "description": "Economists often update beliefs when new evidence arrives."}, {"id": "739960df-b73d-41c0-b968-2926d317da09", "type": "subtopic", "title": "Risk and expected payoff", "children": [{"id": "9233b0f5-569b-42bb-96ac-0154933b2028", "type": "concept", "title": "Expected value"}, {"id": "92bab64a-c88f-45de-9536-6d22909797e9", "type": "concept", "title": "Risk and variance"}, {"id": "dbbe7236-4cff-4824-baf9-1d74b106f224", "type": "concept", "title": "Insurance, lotteries, and portfolio intuition"}], "description": "Probability supports decisions under uncertainty."}]}, {"id": "a89acf6d-8f70-4079-bf8d-49bf95ae61a1", "type": "topic", "title": "Random Variables, Distributions, Expectation, and Moments", "description": "Students learn the probability models and summary quantities behind economic inference.", "children": [{"id": "f2c2ad6b-b28e-487b-8b04-0e164089c8a5", "type": "subtopic", "title": "Random variables", "children": [{"id": "922d5d22-0265-4187-ab5e-b0a0e20b3fcb", "type": "concept", "title": "Discrete and continuous random variables"}, {"id": "e5c5e1e9-aa43-404c-b437-eecee2f14593", "type": "concept", "title": "Probability mass and density functions"}, {"id": "3f549023-43eb-4c44-8f49-b9bc45363913", "type": "concept", "title": "Cumulative distribution functions"}], "description": "Students represent uncertain economic outcomes as variables with probability distributions."}, {"id": "a791dfc6-15bd-4531-bc40-e6136278eeca", "type": "subtopic", "title": "Common distributions", "children": [{"id": "24faf6c9-55bd-45aa-a698-5d8ee14a972b", "type": "concept", "title": "Bernoulli, binomial, and Poisson"}, {"id": "c99ac664-4f8f-49ec-a258-a9c14c53bae8", "type": "concept", "title": "Uniform, normal, lognormal, and t distributions"}, {"id": "1bb057a7-9000-4d9d-af16-8c2e4ce22feb", "type": "concept", "title": "Chi-square and F distributions preview"}], "description": "Standard distributions model common economic data and sampling situations."}, {"id": "7cc8a281-5a90-46f4-a721-897d63fa5af4", "type": "subtopic", "title": "Moments", "children": [{"id": "b3007321-6f69-440b-af80-ed1fead2a8c4", "type": "concept", "title": "Expectation and variance"}, {"id": "07c151dd-78b0-4584-90b3-88e090d307fe", "type": "concept", "title": "Covariance and correlation"}, {"id": "4b73be4a-085e-4db5-9c37-e5cd836f6c50", "type": "concept", "title": "Moment-generating intuition"}], "description": "Moments summarize distributions and support estimator analysis."}]}, {"id": "98c4a4d3-2700-4477-816a-3ebfdd004389", "type": "topic", "title": "Joint, Conditional, and Marginal Distributions", "description": "Economic variables move together; this unit explains dependence, conditioning, covariance, and conditional expectations.", "children": [{"id": "91cad6c1-9a99-41db-b716-ee93f05eda7f", "type": "subtopic", "title": "Joint distributions", "children": [{"id": "7085ec5d-8ad4-4a1d-8be8-5ed51893115a", "type": "concept", "title": "Joint probability tables"}, {"id": "fda8f374-9d9c-460b-b79c-854d78b73b17", "type": "concept", "title": "Joint densities"}, {"id": "2d46586a-99d0-4af6-be07-945eb5048c96", "type": "concept", "title": "Marginalization"}], "description": "Joint distributions describe how economic variables behave together."}, {"id": "9b201e2b-cef4-454e-a54e-67cce6c4f809", "type": "subtopic", "title": "Conditional distributions", "children": [{"id": "4d9550b5-741f-4235-b046-a335d5eae647", "type": "concept", "title": "Conditional means"}, {"id": "e05772e9-f3af-458f-8371-143c53d76b52", "type": "concept", "title": "Conditional variance"}, {"id": "4133273f-b778-4ebd-abe2-a2e2e5af6eff", "type": "concept", "title": "Conditional independence"}], "description": "Conditioning is the basis of comparison, prediction, and regression."}, {"id": "ac0ad376-6cc7-482f-8b77-b2e54646827a", "type": "subtopic", "title": "Dependence", "children": [{"id": "830c6abb-cbf6-4e90-8bd4-346e47023f14", "type": "concept", "title": "Covariance"}, {"id": "92d933e6-d648-4c1a-9b90-afcf133a37c2", "type": "concept", "title": "Correlation"}, {"id": "3aaa69c8-33d8-4f79-bd4b-0f13da46be80", "type": "concept", "title": "Spurious relationships and omitted variables preview"}], "description": "Economic variables are often related, but dependence is not causation."}]}, {"id": "3989ebf6-dd7a-4914-aa2c-7e5f9b4dc19a", "type": "topic", "title": "Sampling, Survey Design, Law of Large Numbers, and Central Limit Theorem", "description": "Students connect data collection to the reliability of sample averages and estimates.", "children": [{"id": "e55c0e42-87fb-427d-ae6b-a411b555d377", "type": "subtopic", "title": "Sampling design", "children": [{"id": "87d3ac61-9e14-4547-bb6e-bb5c259a2ad6", "type": "concept", "title": "Simple random sampling"}, {"id": "15b0a4bb-ecdd-4912-a261-f2fb7591d4a1", "type": "concept", "title": "Stratified and cluster sampling"}, {"id": "ee0fd2cb-2dc3-431a-8bfa-88b2d288a556", "type": "concept", "title": "Survey weights and nonresponse"}], "description": "How data are sampled determines representativeness and uncertainty."}, {"id": "f33d2905-7f9b-483b-8197-b67d99a4e31f", "type": "subtopic", "title": "Sampling distributions", "children": [{"id": "6368fc37-4339-428c-a6b0-95004d7d0fad", "type": "concept", "title": "Sample mean and sample proportion"}, {"id": "5437ffcb-5b28-43eb-9f03-eda64a2a0177", "type": "concept", "title": "Standard error"}, {"id": "08dd0d98-8758-47d2-b8b8-287c15ad278f", "type": "concept", "title": "Simulation of repeated samples"}], "description": "Students learn why sample estimates vary and how to quantify that variation."}, {"id": "efa350f0-e99e-4eaa-ad9b-fe0d253cb428", "type": "subtopic", "title": "Large-sample results", "children": [{"id": "66231c25-4276-4908-a2b8-68006e494ca2", "type": "concept", "title": "Law of large numbers"}, {"id": "cc27a80d-bac1-4623-97c8-d70d6ee9de65", "type": "concept", "title": "Central limit theorem"}, {"id": "8074ee69-8abb-4996-a5e8-4363681f4656", "type": "concept", "title": "Asymptotic approximation and its limits"}], "description": "LLN and CLT explain why averages stabilize and inference often works."}]}, {"id": "2096d87c-733b-4195-892e-8e56b47ca1f6", "type": "topic", "title": "Estimation, Bias, Variance, and Maximum Likelihood", "description": "This unit develops the logic of estimating unknown economic parameters and evaluating estimator quality.", "children": [{"id": "4738668e-ecd3-4cea-be09-bf9bbc8600f3", "type": "subtopic", "title": "Estimator properties", "children": [{"id": "0de8a2ed-df4d-4c5b-bbbc-e0fbf05b2654", "type": "concept", "title": "Bias and unbiasedness"}, {"id": "d512a3a5-f73b-4d9b-b13d-7991a6d79fbc", "type": "concept", "title": "Variance and mean squared error"}, {"id": "a964e31e-e870-49ba-a2de-a372d4339df2", "type": "concept", "title": "Consistency and efficiency intuition"}], "description": "Students evaluate estimates by how they behave across repeated samples."}, {"id": "e5e50e53-74f1-44f3-9643-513012d8e4b7", "type": "subtopic", "title": "Method of moments", "children": [{"id": "18fe7170-3c4f-48a1-aeb8-a3e6d8d97740", "type": "concept", "title": "Sample moments"}, {"id": "fc967780-b841-4c6c-af1a-f3e5531604b0", "type": "concept", "title": "Population moments"}, {"id": "adb3fed5-f494-402d-9655-1eb965135ea6", "type": "concept", "title": "Economic examples such as average treatment or demand parameters"}], "description": "Moment-based estimation links sample summaries to population quantities."}, {"id": "38b2c6e5-3833-42be-a7a6-81226dc795ee", "type": "subtopic", "title": "Maximum likelihood", "children": [{"id": "8ee6fbd7-59b7-4be7-a95a-456cc440942f", "type": "concept", "title": "Likelihood functions"}, {"id": "ee9ee620-4737-4ab0-89bd-39b2d3c4b31b", "type": "concept", "title": "Log-likelihood"}, {"id": "5af61190-df1c-4271-90d1-c4c01f665f28", "type": "concept", "title": "MLE interpretation and standard errors"}], "description": "MLE is a core bridge to econometrics and modern statistical modeling."}]}, {"id": "90fee14d-d389-4317-8066-a6caf81eb657", "type": "topic", "title": "Confidence Intervals and Statistical Uncertainty", "description": "Students learn to report estimates with uncertainty ranges rather than single-number certainty.", "children": [{"id": "18e3da76-9cc5-42c3-95f1-3c4b67d96ec2", "type": "subtopic", "title": "Interval logic", "children": [{"id": "9e2eba69-0c32-4173-9343-62fef78c893e", "type": "concept", "title": "Confidence level"}, {"id": "554cb889-4252-4d9f-8ba0-ebe34a54bffc", "type": "concept", "title": "Margin of error"}, {"id": "f6f7e614-d0d9-4a3c-8c71-5ccbbab45969", "type": "concept", "title": "Coverage interpretation"}], "description": "Intervals communicate plausible values for unknown parameters."}, {"id": "e41f8d15-9c60-492d-9b05-05bcfac0a23d", "type": "subtopic", "title": "Common intervals", "children": [{"id": "f6019472-73c1-404e-aa78-66e779973040", "type": "concept", "title": "Mean and proportion intervals"}, {"id": "01482be5-18ff-4f0b-bd42-1421702c3801", "type": "concept", "title": "Difference in means"}, {"id": "357bb94f-4cc7-43b6-8a7c-3d75391ad31c", "type": "concept", "title": "Regression coefficient intervals preview"}], "description": "Students practice intervals for the quantities economists often report."}, {"id": "cec759a1-329e-4bf8-be36-a0c800c27da4", "type": "subtopic", "title": "Uncertainty communication", "children": [{"id": "387f982c-ea61-46c0-8433-249319f90bca", "type": "concept", "title": "Practical versus statistical precision"}, {"id": "40ec1292-4478-44bd-8bcd-e8d48b925ef1", "type": "concept", "title": "Graphing intervals"}, {"id": "086eeeff-6400-4e23-bad8-b866b5293d7c", "type": "concept", "title": "Uncertainty in policy and business decisions"}], "description": "Economic conclusions should distinguish precision from importance."}]}, {"id": "a7c6fac6-a31e-4449-8e1b-da6b07f9b2c7", "type": "topic", "title": "Hypothesis Testing, p-values, Power, and Multiple Testing", "description": "This unit teaches responsible claim-testing and the limits of statistical significance.", "children": [{"id": "20d2f03b-3893-4003-8f0f-bf6134acde3d", "type": "subtopic", "title": "Testing framework", "children": [{"id": "e2ee7d85-30f9-4e2b-a5fb-d0924622cae0", "type": "concept", "title": "Null and alternative hypotheses"}, {"id": "01514edb-437a-469f-8fb4-ce235b83f269", "type": "concept", "title": "Test statistics"}, {"id": "f9071808-7515-4bba-aaaf-987651d684eb", "type": "concept", "title": "Rejection regions"}], "description": "Hypothesis tests compare observed data to what a null model predicts."}, {"id": "27fa07ad-a423-4007-9ab7-942f8f485a4c", "type": "subtopic", "title": "Interpretation", "children": [{"id": "292c1cdb-61ec-46c6-b6bc-e233a8cc0c6a", "type": "concept", "title": "Type I and Type II errors"}, {"id": "098c9ae4-8d95-4bfc-978a-72828375cdd6", "type": "concept", "title": "p-value meaning"}, {"id": "b1ea04aa-7694-4018-8a24-7aa7a99082eb", "type": "concept", "title": "Effect sizes and economic significance"}], "description": "Students learn what p-values and statistical significance can and cannot say."}, {"id": "6b527fa3-9e58-42af-b98e-e343b27d7542", "type": "subtopic", "title": "Power and multiplicity", "children": [{"id": "0825a8a6-eea4-4e8a-93d8-d71ccd3c0cbc", "type": "concept", "title": "Power and sample size"}, {"id": "1c985080-48a7-4df9-bad4-4b8b3a6eaaab", "type": "concept", "title": "One-sided versus two-sided tests"}, {"id": "734c3df4-41ec-4e79-b76d-baedaa75a6b6", "type": "concept", "title": "Multiple comparisons and false discovery rate"}], "description": "World-class work plans tests and avoids false discovery traps."}]}, {"id": "e3fe73f1-99df-427a-96c9-35969cd7bbde", "type": "topic", "title": "Bivariate Regression, Correlation, and Prediction", "description": "Students begin modeling relationships between economic variables using simple regression and visual diagnostics.", "children": [{"id": "eadab77f-5d1d-4597-8f6c-6bc30edc42a9", "type": "subtopic", "title": "Correlation and scatterplots", "children": [{"id": "782e0d4b-f129-483f-bac1-4c986241c269", "type": "concept", "title": "Pearson and rank correlation"}, {"id": "ae6928fa-aa64-47d9-9d9f-6c42409155e4", "type": "concept", "title": "Outliers and leverage"}, {"id": "67c87b48-3d24-4321-a8ea-695a9e462d45", "type": "concept", "title": "Nonlinear patterns"}], "description": "Students learn to see association before fitting a model."}, {"id": "c911ef7e-8969-4c4d-b49b-c8bdc4033bc4", "type": "subtopic", "title": "Simple linear regression", "children": [{"id": "e14784b9-06a3-46e6-9d8b-59de0ab55d76", "type": "concept", "title": "Slope and intercept"}, {"id": "7c34c8d2-b89b-475b-9260-48246f20cee7", "type": "concept", "title": "Residuals"}, {"id": "03202aaa-f0c9-4f0c-a063-420f4c9df337", "type": "concept", "title": "Least squares intuition"}], "description": "Simple regression estimates a conditional mean relationship between two variables."}, {"id": "f3b2453f-6cff-4f92-8a18-fac2a56b9cf5", "type": "subtopic", "title": "Prediction", "children": [{"id": "fb6c0662-9741-4623-9f36-0726cb4ddafe", "type": "concept", "title": "Fitted values"}, {"id": "28b083e8-0668-488c-9248-8cc3ae5289a4", "type": "concept", "title": "Prediction intervals"}, {"id": "ec6fd771-ad4d-40a1-9f72-902389d64663", "type": "concept", "title": "In-sample versus out-of-sample fit"}], "description": "Regression can predict, but prediction is not causal proof."}]}, {"id": "2d480eab-94f9-4dc0-be78-688b0d274392", "type": "topic", "title": "Multiple Regression for Economic Questions", "description": "This topic develops multivariable models for prediction, adjustment, and economic interpretation.", "children": [{"id": "936b012c-7ed4-4b5c-80ff-aac3208a257f", "type": "subtopic", "title": "Adjusted relationships", "children": [{"id": "ac32940b-815a-413a-a57f-539a26bc102b", "type": "concept", "title": "Partial effects"}, {"id": "0a562635-3fe7-4abc-b3cf-eb8cde2b6b6f", "type": "concept", "title": "Control variables"}, {"id": "09539182-93d6-48db-ac1d-5d15f01960ee", "type": "concept", "title": "Omitted variable bias intuition"}], "description": "Multiple regression compares observations while holding measured covariates fixed."}, {"id": "fe7b7dcc-f4ec-4573-a0d3-846178a283a8", "type": "subtopic", "title": "Economic interpretation", "children": [{"id": "4c15bc73-e2ee-43e8-8be5-96a8823d6243", "type": "concept", "title": "Level-level, log-level, and log-log models"}, {"id": "ed0fed2a-7c45-4844-b7ad-848fc22578f1", "type": "concept", "title": "Dummy variables"}, {"id": "eb48de3b-42be-468a-97fe-e19a0b9104a2", "type": "concept", "title": "Interactions"}], "description": "Coefficients must be translated into units, elasticities, and substantive meaning."}, {"id": "f7397594-4ca5-418d-bce3-22e86ff3d482", "type": "subtopic", "title": "Model building", "children": [{"id": "545712c4-eefd-4127-a764-254fbdc4a89b", "type": "concept", "title": "Confounders versus mediators"}, {"id": "ff0627f9-0537-4394-9674-15174fd48b46", "type": "concept", "title": "Overcontrol"}, {"id": "cf44c213-0bb1-4a40-a953-8617adc00896", "type": "concept", "title": "Specification guided by economic questions"}], "description": "Students learn to choose variables using theory, design, and evidence."}]}, {"id": "ebc4038e-d25b-4b38-b9f6-e903e1d0dd30", "type": "topic", "title": "Regression Diagnostics, Robust Inference, and Model Specification", "description": "Students learn how regression can fail and how economists repair or qualify inference.", "children": [{"id": "671d3a1d-cc02-49c1-96c6-5cc0e3ae60cd", "type": "subtopic", "title": "OLS assumptions", "children": [{"id": "7589d743-fc03-4b48-b7fc-b0ebd661f695", "type": "concept", "title": "Linearity"}, {"id": "c68f6db0-6a7f-4ef7-8639-b1898346108c", "type": "concept", "title": "Exogeneity"}, {"id": "24c989c4-3363-4aa7-8335-5fe95832e5be", "type": "concept", "title": "Homoskedasticity and independence"}], "description": "Assumptions clarify when estimates and standard errors are trustworthy."}, {"id": "3c46969e-db29-4dd3-9dc4-fae22404a1b3", "type": "subtopic", "title": "Diagnostics", "children": [{"id": "47073354-f637-4898-8a5d-e6f5d70bd047", "type": "concept", "title": "Residual plots"}, {"id": "c0a33f91-71d0-4db8-b942-aa156d26c8b0", "type": "concept", "title": "Influential observations"}, {"id": "969f6e47-04a6-44d4-b5fa-af78a1a7a01a", "type": "concept", "title": "Multicollinearity"}], "description": "Students learn to detect problems rather than trust regression output blindly."}, {"id": "2298a8b8-0805-48ee-9632-42354ddd4eb2", "type": "subtopic", "title": "Robust inference", "children": [{"id": "f4472cba-a0b1-4eca-846f-eaf894bb9c79", "type": "concept", "title": "Heteroskedasticity-robust standard errors"}, {"id": "04b953a5-6d14-4659-9274-3655bb56c197", "type": "concept", "title": "Clustered standard errors preview"}, {"id": "ca6ad03b-32c3-4e0d-bf6a-8b84ff868ffd", "type": "concept", "title": "Functional form checks"}], "description": "Economic data often violate textbook conditions, so robust tools are essential."}]}, {"id": "cc97e5b9-e735-468e-accf-50a8004dcaaa", "type": "topic", "title": "Categorical Outcomes, Counts, and Limited Dependent Variables", "description": "This unit extends statistics to binary choices, counts, and outcomes constrained by economic behavior.", "children": [{"id": "5f1b9a8d-1a78-4e8a-83c4-a04a890e6ec5", "type": "subtopic", "title": "Binary outcomes", "children": [{"id": "7b0c9343-a131-4bd3-8787-17792bf8a7cb", "type": "concept", "title": "Linear probability model"}, {"id": "efd6c5ef-6bae-4bae-ba73-c16c25d9ff73", "type": "concept", "title": "Logit and probit intuition"}, {"id": "2c6a94ab-5dd8-459e-a381-dd49721c2a6c", "type": "concept", "title": "Marginal effects"}], "description": "Many economic questions involve choices such as employment, purchase, default, or participation."}, {"id": "2d0f8630-20e7-412c-b4ec-492a2f7dbf03", "type": "subtopic", "title": "Counts and rates", "children": [{"id": "aae87de9-f528-43c1-86cf-cac4ba24482e", "type": "concept", "title": "Poisson model intuition"}, {"id": "d08320ed-a72d-4cb5-936b-62b22e593f2b", "type": "concept", "title": "Rates and exposure"}, {"id": "7dd3c121-925e-4e5d-8c44-a16cbae8dc84", "type": "concept", "title": "Overdispersion preview"}], "description": "Counts arise in patents, visits, claims, events, and transactions."}, {"id": "36b64b45-7232-489e-9823-08510b9dc66f", "type": "subtopic", "title": "Constrained data", "children": [{"id": "ed41f7bf-ab7a-4ad3-b7d3-ea66d83cce6c", "type": "concept", "title": "Tobit intuition"}, {"id": "2ea7a98d-3f87-4707-bce0-98ff8113301f", "type": "concept", "title": "Truncation and censoring"}, {"id": "82f44e75-46ac-4590-985a-82001f5b444f", "type": "concept", "title": "Selection problems preview"}], "description": "Students learn why ordinary regression may mislead when outcomes are bounded or censored."}]}, {"id": "39b8d053-7f98-4088-a324-45a730bf39c9", "type": "topic", "title": "Time Series Basics and Economic Forecasting", "description": "Students analyze economic data indexed over time, including trends, seasonality, autocorrelation, and forecast uncertainty.", "children": [{"id": "b6052eec-ec05-48c8-a05d-9261803d7a56", "type": "subtopic", "title": "Time-series structure", "children": [{"id": "22fd2332-8f0e-489d-a74d-dff3a72119d1", "type": "concept", "title": "Trends and seasonality"}, {"id": "f6695cc1-2d2d-4438-9a69-4c006314ffc4", "type": "concept", "title": "Autocorrelation"}, {"id": "57469826-01be-48f1-b928-943af599de73", "type": "concept", "title": "Stationarity intuition"}], "description": "Economic observations over time require attention to ordering and dependence."}, {"id": "9dfe328e-4cc2-4957-934d-2d35f593f5be", "type": "subtopic", "title": "Forecasting basics", "children": [{"id": "067d24eb-92de-4aa2-9bc2-9db50b6c2973", "type": "concept", "title": "Moving averages"}, {"id": "b1fe6096-a407-43f2-92ec-764a63b4992b", "type": "concept", "title": "Autoregressive models"}, {"id": "3ec1eab1-34f0-4479-a26d-0650f3c1afd4", "type": "concept", "title": "Forecast errors"}], "description": "Students learn simple methods for projecting economic series with uncertainty."}, {"id": "685bef8d-369d-4e05-bc3b-dffec988abbe", "type": "subtopic", "title": "Macroeconomic and financial data", "children": [{"id": "bbfcf291-fa34-43fb-9ee2-d107614698d1", "type": "concept", "title": "FRED data workflows"}, {"id": "347be3eb-4f75-4555-a711-684b2c897f1d", "type": "concept", "title": "Real-time data issues"}, {"id": "6003e8f0-c445-4a23-ba05-4402e9ffe050", "type": "concept", "title": "Structural breaks and regime changes preview"}], "description": "Time series skills connect statistics to inflation, unemployment, GDP, interest rates, and asset prices."}]}, {"id": "345d159b-a900-4d2a-9ff2-940c99bbc8b6", "type": "topic", "title": "Causal Thinking and Research Design Foundations", "description": "The course introduces the bridge from statistics to econometrics: identification, experiments, and credible comparison groups.", "children": [{"id": "a6711bc7-6bc8-4bd0-9b0c-ad1691a6f747", "type": "subtopic", "title": "Correlation versus causation", "children": [{"id": "956d6c91-14c1-4bbe-b952-e9d9b37c2f20", "type": "concept", "title": "Counterfactual logic"}, {"id": "ff1e6ff8-eb8a-43a3-8db3-3303a7abec31", "type": "concept", "title": "Selection bias"}, {"id": "f6fd6e7b-504b-4065-8793-f5f2a65ad525", "type": "concept", "title": "Confounding"}], "description": "Statistics for economists should prepare students to ask whether a comparison identifies an effect."}, {"id": "dd845b35-6670-4111-82ea-541667858a5f", "type": "subtopic", "title": "Experiments", "children": [{"id": "802d5864-db0e-42e9-b685-68518329cd5e", "type": "concept", "title": "Treatment and control groups"}, {"id": "5d7dff6f-3066-45a0-9014-bb0961264e69", "type": "concept", "title": "Average treatment effects"}, {"id": "2f006584-a4f8-4474-9ffa-6f049417d889", "type": "concept", "title": "Compliance and attrition"}], "description": "Random assignment is the benchmark for causal evidence."}, {"id": "a5d76b1a-7506-4233-9f2c-d008d354bdab", "type": "subtopic", "title": "Quasi-experimental previews", "children": [{"id": "9a9ed808-acfe-454b-9967-0b26373d2c42", "type": "concept", "title": "Difference-in-differences"}, {"id": "5262801f-d463-4139-a9db-9eac034ca30b", "type": "concept", "title": "Regression discontinuity"}, {"id": "0549c9c1-9244-4b2e-8661-d2e9a1a12e4b", "type": "concept", "title": "Instrumental variables"}], "description": "Students meet the research designs developed fully in econometrics."}]}, {"id": "c25c9914-31b5-446b-bda4-70bd50b012cd", "type": "topic", "title": "Statistical Computing in Stata, R, or Python", "description": "Students make analysis reproducible, transparent, and ready for economics coursework and empirical research.", "children": [{"id": "902128ae-1b44-4286-8c04-ec0c30d9c388", "type": "subtopic", "title": "Data workflow", "children": [{"id": "58909f0c-f399-4324-a583-2b5e63f2b966", "type": "concept", "title": "Importing and cleaning data"}, {"id": "34241fb2-d7b4-46cf-aec8-0673ae0612f7", "type": "concept", "title": "Data dictionaries"}, {"id": "56d91153-924c-4a40-b11a-ad618adc62bf", "type": "concept", "title": "Merging and reshaping"}], "description": "Students learn to make analysis repeatable rather than manual."}, {"id": "5564a237-4a6d-4443-8b71-f95298cd7cce", "type": "subtopic", "title": "Reproducible analysis", "children": [{"id": "e9cc7038-dd48-4997-8486-81078d70cd54", "type": "concept", "title": "Scripts and notebooks"}, {"id": "0b8035fb-d366-4969-ad59-22502e0cf1d9", "type": "concept", "title": "Versioned outputs"}, {"id": "a5e58d6f-bae3-461b-936a-a7f01180fbb7", "type": "concept", "title": "Tables and figures from code"}], "description": "A reproducible workflow lets others audit, rerun, and extend the analysis."}, {"id": "d86f916c-dbfe-4c2f-8409-8fcf18381d7e", "type": "subtopic", "title": "Software fluency", "children": [{"id": "e9f993a2-585b-4e2c-86f6-ecabe4f0ea06", "type": "concept", "title": "Stata do-files"}, {"id": "815e1f8e-6853-4139-9a52-95fc6d449c32", "type": "concept", "title": "R tidyverse and model summaries"}, {"id": "f839b55e-3684-460c-8db4-223cd37316bd", "type": "concept", "title": "Python pandas and statsmodels"}], "description": "Economic statistics should prepare students for Stata, R, or Python ecosystems."}]}, {"id": "69b81878-8c14-4d4f-ae14-2990ff401342", "type": "topic", "title": "Empirical Economics Capstone", "description": "The course culminates in a full empirical analysis from economic question to data, estimates, uncertainty, and communication.", "children": [{"id": "2e02b9a1-9fa0-4e2d-9585-27e3a540626a", "type": "subtopic", "title": "Question and design", "children": [{"id": "7403e36b-dd41-4e1d-a2bd-d67dbeb14e89", "type": "concept", "title": "Research question"}, {"id": "ef569d9b-9581-4629-bff4-c9d813d06e24", "type": "concept", "title": "Dataset and variables"}, {"id": "fb8b86e4-cfc7-4c0c-8a73-8176882806af", "type": "concept", "title": "Threats to validity"}], "description": "Students define an economic question and choose a defensible empirical approach."}, {"id": "a7ac50f0-ca00-493a-a88d-597063ab4a2f", "type": "subtopic", "title": "Analysis", "children": [{"id": "dc7e5661-de8e-4832-b965-d96cf8da5476", "type": "concept", "title": "Exploratory graphics"}, {"id": "209bf206-6ca7-46be-ba8e-f16940dd735b", "type": "concept", "title": "Estimation and inference"}, {"id": "aa8db925-abef-431f-988a-ca2959ff4539", "type": "concept", "title": "Robustness and sensitivity checks"}], "description": "The capstone demonstrates descriptive, inferential, and regression skills in one workflow."}, {"id": "575e27c8-d972-488b-a039-7083a2be4e82", "type": "subtopic", "title": "Communication", "children": [{"id": "6bd2e1ed-f8e8-4bab-82ed-ee72d718143c", "type": "concept", "title": "Professional regression tables"}, {"id": "bb0dabb2-13bd-4bfa-b200-06a263537f0f", "type": "concept", "title": "Plain-language interpretation"}, {"id": "e0274540-7176-42ff-8f32-d027c2f6f70a", "type": "concept", "title": "Policy or business recommendation"}], "description": "Students present results as economists: clear tables, uncertainty, limitations, and implications."}]}], "dbBacked": true}$stecjson$::jsonb,
